/// passphrase_wordlist.dart — bundled wordlist backing passphrase strength
/// estimation and generation.
///
/// Kept in its own file because it is large (tens of thousands of entries)
/// and otherwise would dwarf the logic in passphrase_strength.dart.
library;

/// Bundled wordlist for [generatePassphrase], and the dictionary used by
/// [estimateStrength] to detect dictionary-word passphrases.
///
/// 40000 common lowercase English words (4-9 letters), sampled uniformly
/// from the macOS/BSD system dictionary (/usr/share/dict/words) with a fixed
/// seed for reproducibility. This is an EFF-style short wordlist, bundled as
/// a Dart constant rather than pulled in as a dependency.
///
/// log2(40000) =~ 15.29 bits of entropy per word, assuming uniform
/// random selection (see [generatePassphrase]). That is deliberately higher
/// than a classic 2048-word EFF list (11 bits/word): the brief requires a
/// *four*-word generated passphrase to already clear [kMinimumEntropyBits]
/// (60 bits) with margin, which needs >= 15 bits/word. Five words give
/// ~76 bits, comfortably clear.
